/**
 *  Fixes flickering fonts by:
 * 1. Preloading font stylesheets
 * 2. Applying a fallback system font immediately
 * 3. Embedding a @font-face block in Global styles
 */
export const StPeterProvider: React.FC<StPeterProviderProps> = ({
  children,
  theme = "neutral",
  font = "Montserrat",
}) => {
  const stPeterTheme = useMemo(
    () => createStPeterSystem(theme, font),
    [theme, font]
  );

  const fontUrl = `https://fonts.googleapis.com/css2?family=${font.replace(
    /\s/g,
    "+"
  )}:wght@400;500;600;700;800&display=swap`;

  return (
    <>
      {/*  Preload fonts before React renders */}
      <link rel="preconnect" href="https://fonts.googleapis.com" />
      <link
        rel="preconnect"
        href="https://fonts.gstatic.com"
        crossOrigin="anonymous"
      />
      <link rel="stylesheet" href={fontUrl} />

      {/*  Apply Global fallback font instantly */}
      <ChakraProvider value={stPeterTheme}>
        <Global
          styles={{
            body: {
              fontFamily: `"${font}", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif`,
              visibility: "visible",
            },
            html: { visibility: "visible" },
          }}
        />
        {children}
      </ChakraProvider>
    </>
  );
};
