"use client";

import {
  IconButton as ChakraIconButton,
  IconButtonProps as ChakraIconButtonProps,
} from "@chakra-ui/react";
import { forwardRef } from "react";

export interface BaseIconButtonProps extends ChakraIconButtonProps {
  variant?: "solid" | "outline" | "ghost";
  size?: "sm" | "md" | "lg" | "xl";
}

export const BaseIconButton = forwardRef<
  HTMLButtonElement,
  BaseIconButtonProps
>(
  (
    {
      variant = "solid",
      size = "md",
      borderRadius,
      p,
      px,
      py,
      pt,
      pb,
      pl,
      pr,
      ...props
    },
    ref
  ) => {
    //  Variant styles
    const styleProps =
      variant === "solid"
        ? {
            bg: "primary",
            color: "primaryForeground",
            _hover: { bg: "primaryHover" },
            _disabled: { bg: "primaryDisabled" },
          }
        : variant === "outline"
        ? {
            bg: "transparent",
            color: "primary",
            borderWidth: "btn-outline-hairline",
            borderColor: "primary",
            _hover: { bg: "primaryHover", color: "primaryForeground" },
            _disabled: {
              borderColor: "primaryDisabled",
              color: "primaryDisabled",
            },
          }
        : {
            bg: "transparent",
            color: "foreground",
            _hover: { bg: "foregroundHover", color: "primaryForeground" },
            _disabled: { color: "primaryDisabled" },
          };
    //  Size styles
    const sizeProps =
      size === "sm"
        ? { boxSize: "btn-h-sm", fontSize: "btn-fs-sm" }
        : size === "lg"
        ? { boxSize: "btn-h-lg", fontSize: "btn-fs-lg" }
        : size === "xl"
        ? { boxSize: "btn-h-xl", fontSize: "btn-fs-xl" }
        : { boxSize: "btn-h-md", fontSize: "btn-fs-md" };

    // Final border radius logic
    // const finalBorderRadius =
    //   borderRadius ?? (size === "sm" ? "sm" : size === "lg" ? "lg" : "md");

    return (
      <ChakraIconButton ref={ref} {...props} {...styleProps} {...sizeProps} />
    );
  }
);

BaseIconButton.displayName = "BaseIconButton";
