// src/recipes/cardSlotRecipe.ts
import { defineSlotRecipe } from "@chakra-ui/react";
import { cardAnatomy } from "../../anatomy/cardAnatomy";

export const cardSlotRecipe = defineSlotRecipe({
  className: "stpeter-card",
  slots: cardAnatomy.keys(),

  base: {
    root: {
      display: "flex",
      flexDirection: "column",
      position: "relative",
      minWidth: 0,
      wordBreak: "break-word",
      borderRadius: "md",          
      color: "foreground",       
      textAlign: "start",
      bg: "background",
    },
    header: {
      paddingInline: "var(--card-padding)",
      paddingTop: "var(--card-padding)",
      display: "flex",
      flexDirection: "column",
      gap: 2,
    },
    body: {
      padding: "var(--card-padding)",
      flex: 1,
      display: "flex",
      flexDirection: "column",
    },
    footer: {
      display: "flex",
      alignItems: "center",
      gap: 3,
      paddingInline: "var(--card-padding)",
      paddingBottom: "var(--card-padding)",
      justifyContent: "flex-end",
    },
    title: {
      fontWeight: "semibold",
    },
    description: {
      color: "foregroundHover", 
      fontSize: "sm",
    },
  },

  variants: {
    size: {
      sm: {
        root: { "--card-padding": "spacing.4" },
        title: { textStyle: "md" },
      },
      md: {
        root: { "--card-padding": "spacing.6" },
        title: { textStyle: "lg" },
      },
      lg: {
        root: { "--card-padding": "spacing.8" },
        title: { textStyle: "xl" },
      },
    },

    variant: {
      elevated: {
        root: {
          bg: "background",
          boxShadow: "md",
        },
      },
      outline: {
        root: {
          bg: "background",
          borderWidth: "1px",
          borderColor: "border",
        },
      },
      subtle: {
        root: {
          bg: "backgroundMuted",
        },
      },
      primary: {
        root: {
          bg: "primary",
          color: "primaryForeground",
          boxShadow: "md",
        },
      },
    },
  },

  defaultVariants: {
    variant: "outline",
    size: "md",
  },
});
