import { BaseCard, BaseCardProps } from "./BaseCard";

export function createLockedCard(
  variant: BaseCardProps["variant"],
  size: BaseCardProps["size"]
) {
  type LockedProps = Omit<
    BaseCardProps,
    | "variant"
    | "size"
    | "bg"
    | "background"
    | "backgroundColor"
    | "color"
    | "border"
    | "borderColor"
    | "borderWidth"
    | "borderRadius"
    | "padding"
    | "p"
    | "pt"
    | "pb"
    | "pl"
    | "pr"
    | "px"
    | "py"
    | "fontSize"
    | "fontWeight"
    | "boxShadow"
    | "shadow"
    | "_hover"
  > & {
    children?: React.ReactNode;
    title?: React.ReactNode;
    description?: React.ReactNode;
    footer?: React.ReactNode;
  };

  return (props: LockedProps) => {
    return <BaseCard {...props} variant={variant} size={size} />;
  };
}
