"use client";
import {
  Card,
  CardHeader,
  CardBody,
  CardFooter,
  CardTitle,
  CardDescription,
  type HTMLChakraProps,
} from "@chakra-ui/react";
import { forwardRef, ReactNode } from "react";

export interface BaseCardProps extends Omit<HTMLChakraProps<"div">, "title"> {
  variant?: "outline" | "elevated" | "subtle";
  size?: "sm" | "md" | "lg";
  cardTitle?: ReactNode;
  description?: ReactNode;
  footer?: ReactNode;
  children?: ReactNode;
}

export const BaseCard = forwardRef<HTMLDivElement, BaseCardProps>(
  (
    {
      variant = "outline",
      size = "md",
      cardTitle,
      description,
      footer,
      children,
      ...props
    },
    ref
  ) => {
    return (
      <Card.Root ref={ref} variant={variant} size={size} {...props}>
        {(cardTitle || description) && (
          <Card.Header>
            {cardTitle && <Card.Title>{cardTitle}</Card.Title>}
            {description && <Card.Description>{description}</Card.Description>}
          </Card.Header>
        )}

        <Card.Body>{children}</Card.Body>

        {footer && <Card.Footer>{footer}</Card.Footer>}
      </Card.Root>
    );
  }
);

BaseCard.displayName = "BaseCard";
