"use client";

import { forwardRef } from "react";
import {
  ButtonGroup as ChakraButtonGroup,
  useSlotRecipe,
} from "@chakra-ui/react";

export interface BaseButtonGroupProps {
  variant?: "solid" | "outline" | "ghost";
  size?: "2xs" | "xs" | "sm" | "md" | "lg" | "xl" | "2xl";
  isAttached?: boolean;
  [key: string]: any;
}

export const BaseButtonGroup = forwardRef<HTMLDivElement, BaseButtonGroupProps>(
  ({ variant = "solid", size = "md", isAttached = false, ...props }, ref) => {
    const recipe = useSlotRecipe({ key: "buttonGroup" });
    const styles = recipe({ variant, size, isAttached });

    return <ChakraButtonGroup ref={ref} css={styles.group} {...props} />;
  }
);

BaseButtonGroup.displayName = "BaseButtonGroup";
