"use client";

import {
  createFlexButton,
  createLockedButton,
  createLockedIconButton,
} from "./ButtonCreators";

export const PrimarySmButton = createLockedButton("solid", "sm");
export const PrimaryMdButton = createLockedButton("solid", "md");
